int kvm_vcpu_create(struct kvm *kvm, u32 id)
{
	int ret;
	struct kvm_vcpu *vcpu;

	if (id >= KVM_MAX_VCPUS)
		return -EINVAL;

	vcpu = kvm_arch_vcpu_create(kvm, id);
	if (!vcpu)
		return -ENOMEM;

	ret = kvm_init_vcpu(vcpu);
	if (ret < 0)
		goto free_vcpu;

	mutex_lock(&kvm->lock);
	if (kvm->online_vcpus >= kvm->max_vcpus) {
		mutex_unlock(&kvm->lock);
		ret = -EINVAL;
		goto free_vcpu;
	}

	if (id < KVM_MAX_VCPUS && kvm->vcpus[id]) {
		mutex_unlock(&kvm->lock);
		ret = -EEXIST;
		goto free_vcpu;
	}

	kvm->vcpus[id] = vcpu;
	kvm->online_vcpus++;
	mutex_unlock(&kvm->lock);

	kvm_set_tss_desc(vcpu);
	kvm_setup_pit_timer(vcpu);

	kvm_arch_vcpu_postcreate(vcpu);

	return 0;

free_vcpu:
	kvm_arch_vcpu_free(vcpu);
	return ret;
}

int kvm_vm_vcpu_create(struct kvm *kvm, u32 id)
{
	int ret;

	if (id >= KVM_MAX_VCPUS)
		return -EINVAL;

	if (kvm->vcpus[id])
		return -EEXIST;

	if (kvm->online_vcpus >= kvm->max_vcpus)
		return -ENOSPC;

	kvm->vcpus[id] = kmalloc(sizeof(struct kvm_vcpu), GFP_KERNEL);
	if (!kvm->vcpus[id])
		return -ENOMEM;

	ret = vcpu_preemption_notifier_init(kvm->vcpus[id]);
	if (ret) {
		kfree(kvm->vcpus[id]);
		return ret;
	}

	kvm->online_vcpus++;
	kvm->userspace_vcpus |= 1 << id;

	ret = kvm_arch_vcpu_postcreate(kvm, kvm->vcpus[id]);
	if (ret) {
		kvm->online_vcpus--;
		kvm->userspace_vcpus &= ~(1 << id);
		kfree(kvm->vcpus[id]);
		return ret;
	}

	return 0;
}

int kvm_create_vcpu(struct kvm *kvm, u32 id)
{
	int ret;
	struct kvm_vcpu *vcpu;

	if (id >= KVM_MAX_VCPUS)
		return -EINVAL;

	vcpu = kvm_vcpu_alloc(kvm, id);
	if (!vcpu)
		return -ENOMEM;

	ret = kvm_vcpu_init(vcpu);
	if (ret < 0)
		goto free_vcpu;

	ret = kvm_setup_vcpu_preemption_notifier(vcpu);
	if (ret < 0)
		goto cleanup_vcpu;

	if (atomic_inc_unless_negative(&kvm->online_vcpus, KVM_MAX_VCPUS - 1) < 0) {
		ret = -ENOSPC;
		goto cleanup_notifier;
	}

	kvm_register_vcpu(kvm, vcpu);

	kvm_arch_post_vcpu_creation(vcpu);

	return 0;

cleanup_notifier:
	kvm_remove_vcpu_notifier(vcpu);
cleanup_vcpu:
	kvm_vcpu_deinit(vcpu);
free_vcpu:
	kvm_vcpu_free(vcpu);
	return ret;
}

int kvm_vcpu_create(struct kvm *kvm, u32 id)
{
	int ret;

	if (id >= KVM_MAX_VCPUS)
		return -EINVAL;

	mutex_lock(&kvm->lock);
	if (kvm->vcpu_count >= KVM_MAX_VCPUS) {
		mutex_unlock(&kvm->lock);
		return -EINVAL;
	}
	if (kvm->vcpus[id]) {
		mutex_unlock(&kvm->lock);
		return -EEXIST;
	}
	mutex_unlock(&kvm->lock);

	kvm->vcpus[id] = kcalloc(1, sizeof(struct kvm_vcpu), GFP_KERNEL);
	if (!kvm->vcpus[id])
		return -ENOMEM;

	kvm->vcpu_count++;
	kvm_setup_preemption_notifier(kvm->vcpus[id]);

	mutex_lock(&kvm->lock);
	ret = kvm_arch_vcpu_create(kvm->vcpus[id]);
	if (ret < 0)
		goto out_free_vcpu;

	kvm_register_vcpu(kvm->vcpus[id]);
	mutex_unlock(&kvm->lock);

	return 0;

out_free_vcpu:
	kvm->vcpu_count--;
	mutex_unlock(&kvm->lock);
	kfree(kvm->vcpus[id]);
	kvm->vcpus[id] = NULL;

	return ret;
}

int kvm_create_vcpu(struct kvm *kvm, u32 id)
{
	int ret;
	struct kvm_vcpu *vcpu;

	if (id >= KVM_MAX_VCPUS)
		return -EINVAL;

	vcpu = kvm_arch_vcpu_create(kvm, id);
	if (!vcpu)
		return -ENOMEM;

	ret = kvm_preempt_notifier_register(vcpu);
	if (ret < 0) {
		kvm_arch_vcpu_free(vcpu);
		return ret;
	}

	if (atomic_read(&kvm->online_vcpus) >= KVM_MAX_VCPUS) {
		kvm_preempt_notifier_unregister(vcpu);
		kvm_arch_vcpu_free(vcpu);
		return -EINVAL;
	}

	kvm->vcpus[id] = vcpu;
	atomic_inc(&kvm->online_vcpus);

	kvm_arch_vcpu_post_create(vcpu);

	return 0;
}
